<script setup lang="ts">import {computed} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Empty from '../components/common/Empty.vue';import InferenceSummary from '../components/InferenceSummary.vue';import StateBands from '../components/StateBands.vue';import RunList from '../components/RunList.vue';const p=defineProps<{studies:any[];traces:any[];profiles:any[];runs:any[];notes:any[]}>();defineEmits(['open']);const run=computed(()=>p.runs.find(r=>r.status==='completed'));const marked=computed(()=>p.runs.reduce((n:number,r:any)=>n+(r.result?.constrained_trace_count||0),0));</script><template><PageTitle index="01" title="同一串观测，两种路径问题。" description="固定HMM假设 → log域前后向 → 边际分布 / Viterbi整段路径 → 工况核对"><a class="primary" href="#config">建立固定模型推断 ↗</a></PageTitle><div class="inventory"><span>{{studies.length}}项研究 / {{profiles.length}}固定版本 / {{traces.length}}条轨迹</span><span>{{traces.filter(t=>t.constraints?.length).length}}条轨迹已标记隐态假设 / {{marked}}条条件推断</span><span>{{notes.filter(n=>n.status==='approved').length}}份核对说明已批准</span></div><template v-if="run"><div class="record-title"><small>LATEST INFERENCE / #{{run.id}}</small><h2>{{run.name}}</h2><button @click="$emit('open',run)">展开后验与联合路径 ↗</button></div><InferenceSummary :result="run.result"/><div class="overview-layout"><StateBands :trace="run.result.traces[0]" :states="run.result.states"/><aside class="margin-note"><small>FIXED MODEL / NOT FAULT FACTS</small><h2>{{run.result.profile.version}}<em> / {{run.result.profile.name}}</em></h2><p>单点最高后验回答每个时刻最可能的状态；Viterbi回答整段最可能路径。拼接单点答案可能违反零转移。</p><p>参数固定，不做EM；带标记轨迹另给条件后验与条件联合路径，无约束似然保留。这里没有真实故障或在线告警结论。</p></aside></div></template><Empty v-else title="还没有可行推断" help="先核对观测字母表与固定π/A/B，再选择最多30条轨迹。"/><section class="section"><h2>推断归档</h2><RunList :runs="runs" @open="$emit('open',$event)"/></section></template>
